#[derive(Debug, Clone)]
pub struct AdmitArgs {
    pub summary: Summary,
    pub source: Option<Source>,
    pub surface: Option<Surface>,
    pub role_name: Option<RoleName>,
    pub actor_id: Option<IdentityId>,
    pub role_gated: Gated,
}

pub fn dispatch_admit(
    repo: &mut impl crate::kernel::Repository<Call>,
    route: Option<&crate::kernel::RoutingEnvelope>,
    args: AdmitArgs,
    mutations: &mut Vec<crate::kernel::MutationRecord>,
    owner_deref: Vec<(&'static str, crate::kernel::DerefNode)>,
    command_deref: Vec<(&'static str, crate::kernel::DerefNode)>,
    tenant_boundary_check: Result<(), crate::kernel::Refusal>,
) -> crate::kernel::DispatchResult<Call> {
    args.summary.check_invariants()?;
    if let Some(v) = &args.role_name {
        v.check_invariants()?;
    }
    if let Some(v) = &args.actor_id {
        v.check_invariants()?;
    }
    let with_references = crate::kernel::WithReferences {
        command_deref: &command_deref,
        args: &args,
        owner_deref: &owner_deref,
    };
    let seed_projections =
        crate::kernel::seeded_projections(&with_references, CALL_PROJECTED_FIELDS);

    crate::kernel::dispatch(
        repo,
        match route {
            Some(__route) => {
                __route.require_depth(0)?;
                crate::kernel::Hydrate::Act {
                    id: __route.aggregate().to_string(),
                }
            }
            None => {
                let __hydrate_id: String = args.summary.value.to_string();
                crate::kernel::Hydrate::Create {
                    id: __hydrate_id,
                    build: Box::new(|| Call {
                        summary: Some(args.summary.clone()),
                        source: args.source.clone(),
                        surface: args.surface.clone(),
                        role_name: args.role_name.clone(),
                        actor_id: args.actor_id.clone(),
                        role_gated: Some(args.role_gated.clone()),
                    }),
                    state_independent: false,
                }
            }
        },
        "Admit",
        "Governance::Call",
        "Call",
        "summary.value",
        &with_references,
        &[
            crate::kernel::GivenSpec {
                description: "an actor names the role it holds",
                expr: Expr::Or(
                    Box::new(Expr::Lookup("actor_id.nil?")),
                    Box::new(Expr::Not(Box::new(Expr::Lookup("role_name.nil?")))),
                ),
                corrects_event: None,
            },
            crate::kernel::GivenSpec {
                description: "a role-gated command has a caller bound",
                expr: Expr::Or(
                    Box::new(Expr::Compare {
                        op: crate::kernel::Comparison {
                            less_than: false,
                            equal: true,
                            negated: true,
                        },
                        left: Box::new(Expr::Lookup("role_gated.value")),
                        right: Box::new(Expr::Str("yes".to_string())),
                    }),
                    Box::new(Expr::Not(Box::new(Expr::Lookup("role_name.nil?")))),
                ),
                corrects_event: None,
            },
        ],
        None,
        |record| {
            let _ = record;
            Ok(())
        },
        &[],
        &call_invariants(),
        &["CallAdmitted"],
        args.to_json(),
        mutations,
        seed_projections,
        tenant_boundary_check,
    )
}

