impl AdmitArgs {
    pub fn from_json(v: &crate::kernel::Json) -> Result<Self, crate::kernel::Refusal> {
        if !matches!(v, crate::kernel::Json::Object(_)) {
            return Err(crate::kernel::Refusal::TypeMismatch(format!(
                "AdmitArgs expects an object, got {}",
                v.inspect()
            )));
        }
        let unknown = v.unknown_keys(&[
            "summary",
            "source",
            "surface",
            "role_name",
            "actor_id",
            "role_gated",
            "id",
        ]);
        if !unknown.is_empty() {
            let unknown: Vec<&str> = unknown.iter().map(String::as_str).collect();
            return Err(crate::kernel::Refusal::UnknownArgument(
                crate::kernel::refusal_wording::UnknownArgumentUnknownArgsArgs {
                    command: "Admit",
                    unknown: &unknown,
                    declared: &[
                        "summary",
                        "source",
                        "surface",
                        "role_name",
                        "actor_id",
                        "role_gated",
                    ],
                }
                .render_args(),
            ));
        }
        let required: &[&str] = &["role_gated", "summary"];
        let absent: Vec<&str> = required
            .iter()
            .copied()
            .filter(|key| v.get(key).is_none())
            .collect();
        if !absent.is_empty() {
            return Err(crate::kernel::Refusal::AbsentArgument(
                crate::kernel::refusal_wording::AbsentArgumentAbsentArgsArgs {
                    command: "Admit",
                    absent: &absent,
                    declared: &[
                        "summary",
                        "source",
                        "surface",
                        "role_name",
                        "actor_id",
                        "role_gated",
                    ],
                }
                .render_args(),
            ));
        }
        let summary = Summary::from_json(
            &(match v.get("summary").ok_or_else(|| {
                crate::kernel::Refusal::TypeMismatch(
                    "Admit.summary expects Summary, got nil".to_string(),
                )
            })? {
                crate::kernel::Json::Null => crate::kernel::Json::Object(Vec::new()),
                other => other.clone(),
            })
            .coerce_single_field("value"),
        )?;
        summary.check_invariants()?;
        let source = match v.get("source") {
            Some(crate::kernel::Json::Null) | None => None,
            Some(x) => Some(Source::from_json(&x.coerce_single_field("value"))?),
        };
        let surface = match v.get("surface") {
            Some(crate::kernel::Json::Null) | None => None,
            Some(x) => Some(Surface::from_json(&x.coerce_single_field("value"))?),
        };
        let role_name = match v.get("role_name") {
            Some(crate::kernel::Json::Null) | None => None,
            Some(x) => Some(RoleName::from_json(&x.coerce_single_field("value"))?),
        };
        if let Some(v) = &role_name {
            v.check_invariants()?;
        }
        let actor_id = match v.get("actor_id") {
            Some(crate::kernel::Json::Null) | None => None,
            Some(x) => Some(IdentityId::from_json(&x.coerce_single_field("value"))?),
        };
        if let Some(v) = &actor_id {
            v.check_invariants()?;
        }
        let role_gated = Gated::from_json(
            &(match v.get("role_gated").ok_or_else(|| {
                crate::kernel::Refusal::TypeMismatch(
                    "Admit.role_gated expects Gated, got nil".to_string(),
                )
            })? {
                crate::kernel::Json::Null => crate::kernel::Json::Object(Vec::new()),
                other => other.clone(),
            })
            .coerce_single_field("value"),
        )?;
        Ok(Self {
            summary,
            source,
            surface,
            role_name,
            actor_id,
            role_gated,
        })
    }
}

impl AdmitArgs {
    pub fn decode_arguments(v: &crate::kernel::Json) -> Result<(), crate::kernel::Refusal> {
        if !matches!(v, crate::kernel::Json::Object(_)) {
            return Err(crate::kernel::Refusal::TypeMismatch(format!(
                "AdmitArgs expects an object, got {}",
                v.inspect()
            )));
        }
        Ok(())
    }

    pub fn refuse_unknown_arguments(v: &crate::kernel::Json) -> Result<(), crate::kernel::Refusal> {
        let unknown = v.unknown_keys(&[
            "summary",
            "source",
            "surface",
            "role_name",
            "actor_id",
            "role_gated",
            "id",
        ]);
        if !unknown.is_empty() {
            let unknown: Vec<&str> = unknown.iter().map(String::as_str).collect();
            crate::kernel::collecting::refuse_each(&unknown, |names| {
                crate::kernel::Refusal::UnknownArgument(
                    crate::kernel::refusal_wording::UnknownArgumentUnknownArgsArgs {
                        command: "Admit",
                        unknown: names,
                        declared: &[
                            "summary",
                            "source",
                            "surface",
                            "role_name",
                            "actor_id",
                            "role_gated",
                        ],
                    }
                    .render_args(),
                )
            })?;
        }
        Ok(())
    }

    pub fn refuse_absent_arguments(v: &crate::kernel::Json) -> Result<(), crate::kernel::Refusal> {
        let required: &[&str] = &["role_gated", "summary"];
        let absent: Vec<&str> = required
            .iter()
            .copied()
            .filter(|key| v.get(key).is_none())
            .collect();
        if !absent.is_empty() {
            crate::kernel::collecting::refuse_each(&absent, |names| {
                crate::kernel::Refusal::AbsentArgument(
                    crate::kernel::refusal_wording::AbsentArgumentAbsentArgsArgs {
                        command: "Admit",
                        absent: names,
                        declared: &[
                            "summary",
                            "source",
                            "surface",
                            "role_name",
                            "actor_id",
                            "role_gated",
                        ],
                    }
                    .render_args(),
                )
            })?;
        }
        Ok(())
    }
}

/// This aggregate's state, or one of its events' payloads, as a caller is answered with
/// it: each single-field value object as its bare field (the shape a command takes it in).
pub fn present(state: crate::kernel::Json) -> crate::kernel::Json {
    match state {
        crate::kernel::Json::Object(fields) => crate::kernel::Json::Object(
            fields
                .into_iter()
                .map(|(k, v)| {
                    let new_v = match k.as_str() {
                        "summary" => match v {
                            crate::kernel::Json::Object(fields) => fields
                                .into_iter()
                                .find(|(k, _)| k == "value")
                                .map_or(crate::kernel::Json::Null, |(_, field_value)| field_value),
                            other => other,
                        },
                        "source" => match v {
                            crate::kernel::Json::Object(fields) => fields
                                .into_iter()
                                .find(|(k, _)| k == "value")
                                .map_or(crate::kernel::Json::Null, |(_, field_value)| field_value),
                            other => other,
                        },
                        "surface" => match v {
                            crate::kernel::Json::Object(fields) => fields
                                .into_iter()
                                .find(|(k, _)| k == "value")
                                .map_or(crate::kernel::Json::Null, |(_, field_value)| field_value),
                            other => other,
                        },
                        "role_name" => match v {
                            crate::kernel::Json::Object(fields) => fields
                                .into_iter()
                                .find(|(k, _)| k == "value")
                                .map_or(crate::kernel::Json::Null, |(_, field_value)| field_value),
                            other => other,
                        },
                        "actor_id" => match v {
                            crate::kernel::Json::Object(fields) => fields
                                .into_iter()
                                .find(|(k, _)| k == "value")
                                .map_or(crate::kernel::Json::Null, |(_, field_value)| field_value),
                            other => other,
                        },
                        "role_gated" => match v {
                            crate::kernel::Json::Object(fields) => fields
                                .into_iter()
                                .find(|(k, _)| k == "value")
                                .map_or(crate::kernel::Json::Null, |(_, field_value)| field_value),
                            other => other,
                        },
                        _ => v,
                    };
                    (k, new_v)
                })
                .collect(),
        ),
        other => other,
    }
}
